(()=>{const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],repo='https://github.com/king0929zion/SparkFlow';const state={match:'nickname',log:'Info',tz:'Asia/Shanghai',days:['0','1','2','3','4','5','6'],accounts:[{username:'Zion',unique_id:'zion0929',cookies:'',targets:['朋友甲','朋友乙']}]};const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));function toast(t){let n=document.createElement('div');n.className='toast';n.textContent=t;$('#toast').append(n);setTimeout(()=>n.remove(),1800)}function log(t){let n=document.createElement('div');n.textContent=`${new Date().toLocaleTimeString()}  ${t}`;$('#logs').append(n);$('#logs').scrollTop=9999}function show(id){$$('.page').forEach(x=>x.classList.toggle('active',x.id===id));$$('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===id));scrollTo(0,0)}function cron(){let h=Math.min(23,Math.max(0,+$('#hour').value||0)),m=Math.min(59,Math.max(0,+$('#minute').value||0)),days=state.days.length===7?'*':state.days.sort().join(','),c=`${m} ${h} * * ${days}`;$('#hour').value=String(h).padStart(2,'0');$('#minute').value=String(m).padStart(2,'0');$('#cronPreview').textContent=`on:\n  workflow_dispatch:\n  schedule:\n    - cron: "${c}"\n      timezone: "${state.tz}"`;$('#mSchedule').textContent=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;$('#mTimezone').textContent=state.tz;return c}function variables(){return{PROXY_ADDRESS:$('#proxy').value,MESSAGE_TEMPLATE:$('#message').value,HITOKOTO_TYPES:$$('#hitokoto .on').map(x=>x.textContent),MATCH_MODE:state.match,BROWSER_TIMEOUT:+$('#browserTimeout').value||120000,FRIEND_LIST_WAIT_TIME:+$('#friendTimeout').value||2000,TASK_RETRY_TIMES:+$('#retry').value||3,LOG_LEVEL:state.log,TASKS:state.accounts.map(a=>({username:a.username,unique_id:a.unique_id,targets:a.targets}))}}function secretNames(){return state.accounts.filter(a=>a.unique_id.trim()).map(a=>`COOKIES_${a.unique_id.trim().toUpperCase()}`)}function renderOutputs(){$('#vars').innerHTML=Object.entries(variables()).map(([k,v])=>`<div class="out"><b>${esc(k)}</b><code>${esc(typeof v==='object'?JSON.stringify(v):v)}</code><button data-copy-var="${esc(k)}">COPY</button></div>`).join('');$('#secrets').innerHTML=secretNames().map(k=>`<div class="out"><b>${esc(k)}</b><code>在 GitHub Environment 中手动填写</code><button data-copy-name="${esc(k)}">COPY NAME</button></div>`).join('')||'<div class="out"><b>NO SECRET KEYS</b><code>请先填写 UNIQUE_ID</code><span></span></div>'}function health(){let goodCookies=state.accounts.length>0&&state.accounts.every(a=>{if(!a.cookies.trim())return false;try{return Array.isArray(JSON.parse(a.cookies))}catch{return false}}),checks=[state.accounts.length>0,goodCookies,state.accounts.every(a=>a.targets.length>0),!!cron()],score=checks.filter(Boolean).length*25;$('#healthScore').textContent=score;$('#healthBar').style.width=score+'%';$('#healthLabel').textContent=score===100?'READY':score>=50?'CHECK':'ERROR';$('#healthList').innerHTML=['accounts','cookies','targets','schedule'].map((k,i)=>`<li>${checks[i]?'+':'!'} ${k} ${checks[i]?'ready':'pending'}</li>`).join('');$('#mConfig').textContent=score===100?'READY':'CHECK';return score}function refresh(){$('#mAccounts').textContent=state.accounts.length;$('#mTargets').textContent=state.accounts.reduce((n,a)=>n+a.targets.length,0);renderOutputs();health()}function renderAccounts(){let r=$('#accountsList');r.innerHTML='';state.accounts.forEach((a,i)=>{let n=document.createElement('article');n.className='account';n.innerHTML=`<div class="account-head"><b>ACCOUNT ${String(i+1).padStart(2,'0')} · ${esc(a.username||'UNNAMED')}</b><button data-remove="${i}">REMOVE</button></div><div class="account-body"><label>USERNAME<input data-i="${i}" data-k="username" value="${esc(a.username)}"></label><label>UNIQUE_ID<input data-i="${i}" data-k="unique_id" value="${esc(a.unique_id)}"></label><label class="full">COOKIES / JSON<textarea class="cookie" data-i="${i}" data-k="cookies" placeholder="仅用于当前页面本地格式校验，不会保存或导出">${esc(a.cookies)}</textarea></label><label class="full">TARGETS<div class="add-target"><input data-target-input="${i}" placeholder="输入好友"><button data-add-target="${i}">ADD</button></div><div class="targets">${a.targets.map((t,j)=>`<span class="tag">${esc(t)}<button data-del-target="${i}:${j}">×</button></span>`).join('')}</div></label></div>`;r.append(n)});refresh()}async function copy(v){try{await navigator.clipboard.writeText(v);toast('已复制')}catch{toast('复制失败')}}function validate(){let issues=[];state.accounts.forEach((a,i)=>{if(!a.unique_id.trim())issues.push(`账号 ${i+1}: UNIQUE_ID 缺失`);if(!a.targets.length)issues.push(`账号 ${i+1}: 无目标好友`);if(!a.cookies.trim())issues.push(`账号 ${i+1}: Cookies 未填写`);else try{if(!Array.isArray(JSON.parse(a.cookies)))issues.push(`账号 ${i+1}: Cookies 应为 JSON 数组`)}catch{issues.push(`账号 ${i+1}: Cookies JSON 无效`)}});if(issues.length){issues.forEach(x=>log('WARN '+x));toast(`发现 ${issues.length} 个问题`);return}log('PRE-FLIGHT PASS');toast('配置预检通过')}function save(){let d={match:state.match,log:state.log,tz:state.tz,days:state.days,accounts:state.accounts.map(a=>({username:a.username,unique_id:a.unique_id,cookies:'',targets:a.targets})),message:$('#message').value,browser:$('#browserTimeout').value,friend:$('#friendTimeout').value,retry:$('#retry').value,proxy:$('#proxy').value,hour:$('#hour').value,minute:$('#minute').value,hitokoto:$$('#hitokoto .on').map(x=>x.textContent)};localStorage.setItem('sparkflow-draft-v31',JSON.stringify(d));toast('非敏感草稿已保存')}function load(){try{let d=JSON.parse(localStorage.getItem('sparkflow-draft-v31')||'null');if(!d)return;state.match=d.match||state.match;state.log=d.log||state.log;state.tz=d.tz||state.tz;state.days=d.days||state.days;state.accounts=d.accounts?.length?d.accounts:state.accounts;$('#message').value=d.message||$('#message').value;$('#browserTimeout').value=d.browser||120000;$('#friendTimeout').value=d.friend||2000;$('#retry').value=d.retry||3;$('#proxy').value=d.proxy||'';$('#hour').value=d.hour||'09';$('#minute').value=d.minute||'07'}catch{}}document.addEventListener('click',e=>{let p=e.target.closest('[data-panel]');if(p){show(p.dataset.panel);return}let a=e.target.closest('[data-do]')?.dataset.do;if(a){if(a==='validate')validate();if(a==='actions')open(repo+'/actions','_blank');if(a==='save')save();if(a==='addAccount'){state.accounts.push({username:'',unique_id:'',cookies:'',targets:[]});renderAccounts()}if(a==='copyCron')copy($('#cronPreview').textContent);if(a==='copyVars')copy(Object.entries(variables()).map(([k,v])=>`${k}=${typeof v==='object'?JSON.stringify(v):String(v).replaceAll('\n','\\n')}`).join('\n'));if(a==='copySecrets')copy(secretNames().join('\n'));if(a==='clear')$('#logs').innerHTML='';return}let trigger=e.target.closest('.select-btn');if(trigger){let s=trigger.closest('.select');$$('.select.open').filter(x=>x!==s).forEach(x=>x.classList.remove('open'));s.classList.toggle('open');return}let opt=e.target.closest('.menu button');if(opt){let s=opt.closest('.select'),v=opt.textContent;s.classList.remove('open');$('.select-btn',s).textContent=v+'⌄';$$('.menu button',s).forEach(x=>x.classList.toggle('on',x===opt));if(s.dataset.key==='log')state.log=v;if(s.dataset.key==='tz')state.tz=v;refresh();return}let seg=e.target.closest('#match button');if(seg){state.match=seg.dataset.value;$$('#match button').forEach(x=>x.classList.toggle('on',x===seg));refresh()}let chip=e.target.closest('#hitokoto button');if(chip){chip.classList.toggle('on');refresh()}let day=e.target.closest('#days button');if(day){day.classList.toggle('on');state.days=$$('#days .on').map(x=>x.dataset.day);cron()}let step=e.target.closest('[data-step]');if(step){$('#retry').value=Math.max(1,(+$('#retry').value||1)+(+step.dataset.step));refresh()}let rem=e.target.closest('[data-remove]');if(rem){state.accounts.splice(+rem.dataset.remove,1);renderAccounts()}let add=e.target.closest('[data-add-target]');if(add){let i=+add.dataset.addTarget,input=$(`[data-target-input="${i}"]`),v=input.value.trim();if(v){state.accounts[i].targets.push(v);renderAccounts()}}let del=e.target.closest('[data-del-target]');if(del){let[i,j]=del.dataset.delTarget.split(':').map(Number);state.accounts[i].targets.splice(j,1);renderAccounts()}let cv=e.target.closest('[data-copy-var]');if(cv){let v=variables()[cv.dataset.copyVar];copy(typeof v==='object'?JSON.stringify(v):String(v))}let cn=e.target.closest('[data-copy-name]');if(cn)copy(cn.dataset.copyName)});document.addEventListener('input',e=>{if(e.target.matches('[data-i][data-k]'))state.accounts[+e.target.dataset.i][e.target.dataset.k]=e.target.value;if(['hour','minute'].includes(e.target.id))cron();refresh()});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-target-input]')){e.preventDefault();$(`[data-add-target="${e.target.dataset.targetInput}"]`).click()}});$('#consoleForm').addEventListener('submit',e=>{e.preventDefault();let c=$('#cmd').value.trim();$('#cmd').value='';log('$ '+c);if(c==='help')log('status validate dashboard config accounts schedule deploy actions save clear');else if(c==='status')log(`accounts=${state.accounts.length} targets=${state.accounts.reduce((n,a)=>n+a.targets.length,0)} health=${health()}`);else if(c==='validate')validate();else if(['dashboard','config','accounts','schedule','deploy'].includes(c))show(c);else if(c==='actions')open(repo+'/actions','_blank');else if(c==='save')save();else if(c==='clear')$('#logs').innerHTML='';else if(c)log('command not found')});setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false}),1000);load();renderAccounts();cron();refresh();log('SparkFlow Control Center v3.1 booted');})();
